window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6eee94231fed8643"]={"versions": [{"id": "FIG-6eee94231fed8643", "releases": ["R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> PDU-Layout / Protokoll-Frame-Bitfelddefinition (Binäres Paketformat auf Schicht 5–7 gemäß AUTOSAR FO PRS Intrusion Detection System).\n</li><li><strong>Technischer Zweck:</strong> Das Diagramm spezifiziert die 8-Byte-Basiseinheit (<code>Event Frame</code>) des AUTOSAR IDS-Nachrichtenformats zur standardisierten Übertragung von sicherheitsrelevanten Vorfällen (Security Events) zwischen Intrusion Detection System Managern (IdsM) oder zur Weiterleitung an fahrzeuginterne/-externe Auswerteeinheiten (z. B. On-Board Security Event Collector / SIEM).\n</li><li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong>\n<ul class=\"fig-list\"><li>Das Gesamtprotokoll ist modular strukturiert: Auf den obligatorischen <code>Event Frame</code> können optional <code>Timestamp</code>, <code>Context Data Frame</code> und <code>Signature Frame</code> folgen.\n</li><li>Gemäß <code>[PRS_Ids_00005]</code> ist das Format hardware- und busunabhängig (CAN, CAN FD, Ethernet/SOME/IP, FlexRay), jedoch mit exakt 8 Bytes so ausgelegt, dass ein minimaler Security-Event-Report verlustfrei und ohne Segmentierung in einen klassischen CAN-Standard-Frame (Payload-Länge DLC = 8) passt.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Übergeordneter Protokollverbund (Frame-Hierarchie)</h5>\n<ul class=\"fig-list\"><li><strong><code>Event Frame</code> (obligatorisch, 8 Bytes):</strong> Minimale Metadatenstruktur zur Identifikation und Zählung des Vorfalls.\n</li><li><strong><code>Timestamp</code> (optional):</strong> Zeitstempel zur Korrelation (üblicherweise aus Synchronized Time-Base, z. B. StbM / IEEE 802.1AS).\n</li><li><strong><code>Context Data Frame</code> (optional):</strong> Erweiterte Rohdaten/Umgebungsdaten des gemeldeten Events (z. B. gefilterte CAN-Payload, CPU-Status).\n</li><li><strong><code>Signature Frame</code> (optional):</strong> Kryptografischer Integritäts- und Authentizitätsnachweis (z. B. via Crypto Stack / Csm / SecOC berechneter MAC oder digitale Signatur).\n</li></ul>\n<h5 class=\"fig-section-h5\">Bitfeld-Layout des Event Frames (Byte 0 bis Byte 7, Big-Endian / Motorola gem. <code>[PRS_Ids_00004]</code>)</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Byte</th><th>Bit-Bereich</th><th>Feldname</th><th>Breite</th><th>Beschreibung &amp; Wertebereich</th></tr></thead><tbody><tr><td><strong>Byte 0</strong></td><td>Bit 7 (MSB) .. 4 (LSB)</td><td><code>Protocol Version</code></td><td>4 Bits</td><td>Version des IDS-Protokolls zur Gewährleistung von Interoperabilität und Dekodierbarkeit über Plattform-Releases hinweg.</td></tr><tr><td><strong>Byte 0</strong></td><td>Bit 3 (MSB) .. 0 (LSB)</td><td><code>Protocol Header</code></td><td>4 Bits</td><td>Steuerungsinformationen / Flags (z. B. Indikatoren für nachfolgende optionale Segmente: Timestamp, Context Data, Signature).</td></tr><tr><td><strong>Byte 1–2</strong></td><td>Byte 1 Bit 7..0 &amp; Byte 2 Bit 7..6</td><td><code>IdsM Instance ID</code></td><td>10 Bits</td><td>Eindeutige Instanzkennung des meldenden IdsM-Moduls im Steuergeräte-Verbund (Wertbereich: 0 .. 1023).</td></tr><tr><td><strong>Byte 2</strong></td><td>Byte 2 Bit 5 (MSB) .. 0 (LSB)</td><td><code>Sensor Instance ID</code></td><td>6 Bits</td><td>Identifikator der meldenden Sensor-Instanz (Hard- oder Software-Sensor innerhalb der Plattform, Wertbereich: 0 .. 63).</td></tr><tr><td><strong>Byte 3–4</strong></td><td>Byte 3 Bit 7..0 &amp; Byte 4 Bit 7..0</td><td><code>Event Definition ID</code></td><td>16 Bits</td><td>Standardisierte oder herstellerspezifische Vorfall-ID (Security Event Typ gem. AUTOSAR Security Event Katalog / ARXML).</td></tr><tr><td><strong>Byte 5–6</strong></td><td>Byte 5 Bit 7..0 &amp; Byte 6 Bit 7..0</td><td><code>Count</code></td><td>16 Bits</td><td>Monoton steigender Sequenz- bzw. Ereigniszähler (Erkennung von Event-Aggregation, Burst-Verhalten oder Frame-Loss / Anti-Replay).</td></tr><tr><td><strong>Byte 7</strong></td><td>Bit 7 (MSB) .. 0 (LSB)</td><td><code>Reserved</code></td><td>8 Bits</td><td>Reserviertes Padding-/Zukunftsfeld; standardmäßig auf <code>0x00</code> zu setzen (sofern nicht durch spätere Profile redefiniert).</td></tr></tbody></table></div>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Ein On-Board-Sensor (z. B. CanSM/CanIf-Filter, SecOC-MAC-Fehler, Firewall, Dem oder Applikations-SW-C) detektiert eine Security-Anomalie und ruft die IdsM-API auf:\n<ul class=\"fig-list\"><li>CP: <code>IdsM_SetSecurityEvent(EventDefinitionId, ...)</code>\n</li><li>AP: <code>ara::idsm::ReportSecurityEvent(...)</code>\n</li></ul>\n</li><li><strong>Filterung &amp; Aggregation (IdsM-intern):</strong>\n<ul class=\"fig-list\"><li>Der IdsM validiert und filtert das Event (Thresholding, Rate-Limiting, Blacklisting).\n</li><li>Bei wiederholtem Auftreten desselben Events innerhalb eines Aggregationsintervalls wird der <code>Count</code>-Parameter inkrementiert, anstatt für jeden Vorfall eine separate Bus-PDU zu erzeugen.\n</li></ul>\n</li><li><strong>PDU-Serialisierung (Big-Endian-Serialisierung):</strong>\n<ul class=\"fig-list\"><li>Der IdsM generiert den 8-Byte-<code>Event Frame</code> strikt in Network Byte Order (Byte 0 zuerst; MSB in Bit 7).\n</li><li>Wenn konfiguriert, werden Zeitstempel (via StbM) und Kontextdaten angehängt sowie ein Signature-Trailer via CSM/SecOC ergänzt.\n</li></ul>\n</li><li><strong>PDU-Übergabe an den Communication Stack:</strong>\n<ul class=\"fig-list\"><li>Übergabe als I-PDU an PduR / Com bzw. Ethernet Socket/SOME/IP.\n</li><li>Asynchrone Sendebestätigung über <code>TxConfirmation</code>. Fehlerbehandlung bei Sendeverzug oder PDU-Pufferüberlauf erfolgt via Det (<code>IDSM_E_PARAM_POINTER</code>, <code>IDSM_E_FIFO_OVERFLOW</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Endianness (<code>[PRS_Ids_00004]</code>):</strong> \n<ul class=\"fig-list\"><li>Verbindliche Ausrichtung auf <strong>Big-Endian (Motorola-Format)</strong>. Auf Little-Endian-Zielarchitekturen (z. B. ARM Cortex-M/R/A, x86/AURIX-spezifische Little-Endian-Cores) ist eine explizite Byte-/Bit-Invertierung bzw. Shift-Maskierung für die 10-Bit (<code>IdsM Instance ID</code>) und 16-Bit (<code>Event Definition ID</code>, <code>Count</code>) Multi-Byte-Werte zwingend erforderlich.\n</li></ul>\n</li><li><strong>Byte-Übergreifende Bitfelder (Byte 1 &amp; Byte 2):</strong>\n<ul class=\"fig-list\"><li><code>IdsM Instance ID</code> überspannt die Grenze zwischen Byte 1 und Byte 2 (Bit 7..6). Es darf kein naiver C-Bitfield-Struct verwendet werden, da Compiler-Implementierungen bezüglich Bitfeld-Packing und Endianness nicht portabel sind. Bit-Maskierung muss über standardisierte Shift-Operationen realisiert werden:\n $$\\text{Byte 1} = (\\text{IdsM\\_InstanceId} \\gg 2) \\ \\&amp; \\ \\text{0xFF}$$\n $$\\text{Byte 2} = ((\\text{IdsM\\_InstanceId} \\ \\&amp; \\ \\text{0x03}) \\ll 6) \\mid (\\text{Sensor\\_InstanceId} \\ \\&amp; \\ \\text{0x3F})$$\n</li></ul>\n</li><li><strong>CAN-Payload-Optimierung (<code>[PRS_Ids_00005]</code>, <code>[PRS_Ids_00006]</code>):</strong>\n<ul class=\"fig-list\"><li>Werden für ein Event weder Kontextdaten noch Timestamps/Signaturen konfiguriert (<code>Protocol Header = 0</code>), entspricht die resultierende PDU exakt 8 Bytes. Dies ermöglicht die direkte Übertragung via Classical CAN ohne Transportprotokoll (CanTp).\n</li></ul>\n</li><li><strong>Konfigurationsverträge (ARXML / BswM):</strong>\n<ul class=\"fig-list\"><li><code>Event Definition ID</code> muss konsistent mit dem BSW-Modul <code>IdsM</code> über standardisierte IDs aus dem Security-Modell gemappt sein.\n</li><li>Das <code>Reserved</code>-Byte (Byte 7) muss vom Transmitter auf <code>0x00</code> initialisiert und vom Receiver tolerant behandelt (ignoriert) werden, um Vorwärtskompatibilität zu wahren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-54798a7e9de401df", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> PDU-Layout / Protokoll-Frame-Bitfelddefinition (Binäres Paketformat auf Schicht 5–7 gemäß AUTOSAR FO PRS Intrusion Detection System).\n</li><li><strong>Technischer Zweck:</strong> Das Diagramm spezifiziert die 8-Byte-Basiseinheit (<code>Event Frame</code>) des AUTOSAR IDS-Nachrichtenformats zur standardisierten Übertragung von sicherheitsrelevanten Vorfällen (Security Events) zwischen Intrusion Detection System Managern (IdsM) oder zur Weiterleitung an fahrzeuginterne/-externe Auswerteeinheiten (z. B. On-Board Security Event Collector / SIEM).\n</li><li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong>\n<ul class=\"fig-list\"><li>Das Gesamtprotokoll ist modular strukturiert: Auf den obligatorischen <code>Event Frame</code> können optional <code>Timestamp</code>, <code>Context Data Frame</code> und <code>Signature Frame</code> folgen.\n</li><li>Gemäß <code>[PRS_Ids_00005]</code> ist das Format hardware- und busunabhängig (CAN, CAN FD, Ethernet/SOME/IP, FlexRay), jedoch mit exakt 8 Bytes so ausgelegt, dass ein minimaler Security-Event-Report verlustfrei und ohne Segmentierung in einen klassischen CAN-Standard-Frame (Payload-Länge DLC = 8) passt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Übergeordneter Protokollverbund (Frame-Hierarchie)</h5>\n<ul class=\"fig-list\"><li><strong><code>Event Frame</code> (obligatorisch, 8 Bytes):</strong> Minimale Metadatenstruktur zur Identifikation und Zählung des Vorfalls.\n</li><li><strong><code>Timestamp</code> (optional):</strong> Zeitstempel zur Korrelation (üblicherweise aus Synchronized Time-Base, z. B. StbM / IEEE 802.1AS).\n</li><li><strong><code>Context Data Frame</code> (optional):</strong> Erweiterte Rohdaten/Umgebungsdaten des gemeldeten Events (z. B. gefilterte CAN-Payload, CPU-Status).\n</li><li><strong><code>Signature Frame</code> (optional):</strong> Kryptografischer Integritäts- und Authentizitätsnachweis (z. B. via Crypto Stack / Csm / SecOC berechneter MAC oder digitale Signatur).\n</li></ul>\n<h5 class=\"fig-section-h5\">Bitfeld-Layout des Event Frames (Byte 0 bis Byte 7, Big-Endian / Motorola gem. <code>[PRS_Ids_00004]</code>)</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Byte</th><th>Bit-Bereich</th><th>Feldname</th><th>Breite</th><th>Beschreibung &amp; Wertebereich</th></tr></thead><tbody><tr><td><strong>Byte 0</strong></td><td>Bit 7 (MSB) .. 4 (LSB)</td><td><code>Protocol Version</code></td><td>4 Bits</td><td>Version des IDS-Protokolls zur Gewährleistung von Interoperabilität und Dekodierbarkeit über Plattform-Releases hinweg.</td></tr><tr><td><strong>Byte 0</strong></td><td>Bit 3 (MSB) .. 0 (LSB)</td><td><code>Protocol Header</code></td><td>4 Bits</td><td>Steuerungsinformationen / Flags (z. B. Indikatoren für nachfolgende optionale Segmente: Timestamp, Context Data, Signature).</td></tr><tr><td><strong>Byte 1–2</strong></td><td>Byte 1 Bit 7..0 &amp; Byte 2 Bit 7..6</td><td><code>IdsM Instance ID</code></td><td>10 Bits</td><td>Eindeutige Instanzkennung des meldenden IdsM-Moduls im Steuergeräte-Verbund (Wertbereich: 0 .. 1023).</td></tr><tr><td><strong>Byte 2</strong></td><td>Byte 2 Bit 5 (MSB) .. 0 (LSB)</td><td><code>Sensor Instance ID</code></td><td>6 Bits</td><td>Identifikator der meldenden Sensor-Instanz (Hard- oder Software-Sensor innerhalb der Plattform, Wertbereich: 0 .. 63).</td></tr><tr><td><strong>Byte 3–4</strong></td><td>Byte 3 Bit 7..0 &amp; Byte 4 Bit 7..0</td><td><code>Event Definition ID</code></td><td>16 Bits</td><td>Standardisierte oder herstellerspezifische Vorfall-ID (Security Event Typ gem. AUTOSAR Security Event Katalog / ARXML).</td></tr><tr><td><strong>Byte 5–6</strong></td><td>Byte 5 Bit 7..0 &amp; Byte 6 Bit 7..0</td><td><code>Count</code></td><td>16 Bits</td><td>Monoton steigender Sequenz- bzw. Ereigniszähler (Erkennung von Event-Aggregation, Burst-Verhalten oder Frame-Loss / Anti-Replay).</td></tr><tr><td><strong>Byte 7</strong></td><td>Bit 7 (MSB) .. 0 (LSB)</td><td><code>Reserved</code></td><td>8 Bits</td><td>Reserviertes Padding-/Zukunftsfeld; standardmäßig auf <code>0x00</code> zu setzen (sofern nicht durch spätere Profile redefiniert).</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Ein On-Board-Sensor (z. B. CanSM/CanIf-Filter, SecOC-MAC-Fehler, Firewall, Dem oder Applikations-SW-C) detektiert eine Security-Anomalie und ruft die IdsM-API auf:\n<ul class=\"fig-list\"><li>CP: <code>IdsM_SetSecurityEvent(EventDefinitionId, ...)</code>\n</li><li>AP: <code>ara::idsm::ReportSecurityEvent(...)</code>\n</li></ul>\n</li><li><strong>Filterung &amp; Aggregation (IdsM-intern):</strong>\n<ul class=\"fig-list\"><li>Der IdsM validiert und filtert das Event (Thresholding, Rate-Limiting, Blacklisting).\n</li><li>Bei wiederholtem Auftreten desselben Events innerhalb eines Aggregationsintervalls wird der <code>Count</code>-Parameter inkrementiert, anstatt für jeden Vorfall eine separate Bus-PDU zu erzeugen.\n</li></ul>\n</li><li><strong>PDU-Serialisierung (Big-Endian-Serialisierung):</strong>\n<ul class=\"fig-list\"><li>Der IdsM generiert den 8-Byte-<code>Event Frame</code> strikt in Network Byte Order (Byte 0 zuerst; MSB in Bit 7).\n</li><li>Wenn konfiguriert, werden Zeitstempel (via StbM) und Kontextdaten angehängt sowie ein Signature-Trailer via CSM/SecOC ergänzt.\n</li></ul>\n</li><li><strong>PDU-Übergabe an den Communication Stack:</strong>\n<ul class=\"fig-list\"><li>Übergabe als I-PDU an PduR / Com bzw. Ethernet Socket/SOME/IP.\n</li><li>Asynchrone Sendebestätigung über <code>TxConfirmation</code>. Fehlerbehandlung bei Sendeverzug oder PDU-Pufferüberlauf erfolgt via Det (<code>IDSM_E_PARAM_POINTER</code>, <code>IDSM_E_FIFO_OVERFLOW</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Endianness (<code>[PRS_Ids_00004]</code>):</strong> \n<ul class=\"fig-list\"><li>Verbindliche Ausrichtung auf <strong>Big-Endian (Motorola-Format)</strong>. Auf Little-Endian-Zielarchitekturen (z. B. ARM Cortex-M/R/A, x86/AURIX-spezifische Little-Endian-Cores) ist eine explizite Byte-/Bit-Invertierung bzw. Shift-Maskierung für die 10-Bit (<code>IdsM Instance ID</code>) und 16-Bit (<code>Event Definition ID</code>, <code>Count</code>) Multi-Byte-Werte zwingend erforderlich.\n</li></ul>\n</li><li><strong>Byte-Übergreifende Bitfelder (Byte 1 &amp; Byte 2):</strong>\n<ul class=\"fig-list\"><li><code>IdsM Instance ID</code> überspannt die Grenze zwischen Byte 1 und Byte 2 (Bit 7..6). Es darf kein naiver C-Bitfield-Struct verwendet werden, da Compiler-Implementierungen bezüglich Bitfeld-Packing und Endianness nicht portabel sind. Bit-Maskierung muss über standardisierte Shift-Operationen realisiert werden:\n $$\\text{Byte 1} = (\\text{IdsM\\_InstanceId} \\gg 2) \\ \\&amp; \\ \\text{0xFF}$$\n $$\\text{Byte 2} = ((\\text{IdsM\\_InstanceId} \\ \\&amp; \\ \\text{0x03}) \\ll 6) \\mid (\\text{Sensor\\_InstanceId} \\ \\&amp; \\ \\text{0x3F})$$\n</li></ul>\n</li><li><strong>CAN-Payload-Optimierung (<code>[PRS_Ids_00005]</code>, <code>[PRS_Ids_00006]</code>):</strong>\n<ul class=\"fig-list\"><li>Werden für ein Event weder Kontextdaten noch Timestamps/Signaturen konfiguriert (<code>Protocol Header = 0</code>), entspricht die resultierende PDU exakt 8 Bytes. Dies ermöglicht die direkte Übertragung via Classical CAN ohne Transportprotokoll (CanTp).\n</li></ul>\n</li><li><strong>Konfigurationsverträge (ARXML / BswM):</strong>\n<ul class=\"fig-list\"><li><code>Event Definition ID</code> muss konsistent mit dem BSW-Modul <code>IdsM</code> über standardisierte IDs aus dem Security-Modell gemappt sein.\n</li><li>Das <code>Reserved</code>-Byte (Byte 7) muss vom Transmitter auf <code>0x00</code> initialisiert und vom Receiver tolerant behandelt (ignoriert) werden, um Vorwärtskompatibilität zu wahren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-831d59b7d249c1c8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> PDU-Layout / Protokoll-Frame-Bitfelddefinition (Binäres Paketformat auf Schicht 5–7 gemäß AUTOSAR FO PRS Intrusion Detection System).\n</li><li><strong>Technischer Zweck:</strong> Das Diagramm spezifiziert die 8-Byte-Basiseinheit (<code>Event Frame</code>) des AUTOSAR IDS-Nachrichtenformats zur standardisierten Übertragung von sicherheitsrelevanten Vorfällen (Security Events) zwischen Intrusion Detection System Managern (IdsM) oder zur Weiterleitung an fahrzeuginterne/-externe Auswerteeinheiten (z. B. On-Board Security Event Collector / SIEM).\n</li><li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong>\n<ul class=\"fig-list\"><li>Das Gesamtprotokoll ist modular strukturiert: Auf den obligatorischen <code>Event Frame</code> können optional <code>Timestamp</code>, <code>Context Data Frame</code> und <code>Authenticator Frame</code> folgen.\n</li><li>Gemäß <code>[PRS_Ids_00005]</code> ist das Format hardware- und busunabhängig (CAN, CAN FD, Ethernet/SOME/IP, FlexRay), jedoch mit exakt 8 Bytes so ausgelegt, dass ein minimaler Security-Event-Report verlustfrei und ohne Segmentierung in einen klassischen CAN-Standard-Frame (Payload-Länge DLC = 8) passt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Übergeordneter Protokollverbund (Frame-Hierarchie)</h5>\n<ul class=\"fig-list\"><li><strong><code>Event Frame</code> (obligatorisch, 8 Bytes):</strong> Minimale Metadatenstruktur zur Identifikation und Zählung des Vorfalls.\n</li><li><strong><code>Timestamp</code> (optional):</strong> Zeitstempel zur Korrelation (üblicherweise aus Synchronized Time-Base, z. B. StbM / IEEE 802.1AS).\n</li><li><strong><code>Context Data Frame</code> (optional):</strong> Erweiterte Rohdaten/Umgebungsdaten des gemeldeten Events (z. B. gefilterte CAN-Payload, CPU-Status).\n</li><li><strong><code>Authenticator Frame</code> (optional):</strong> Kryptografischer Integritäts- und Authentizitätsnachweis (z. B. via Crypto Stack / Csm / SecOC berechneter MAC oder digitale Signatur).\n</li></ul>\n<h5 class=\"fig-section-h5\">Bitfeld-Layout des Event Frames (Byte 0 bis Byte 7, Big-Endian / Motorola gem. <code>[PRS_Ids_00004]</code>)</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Byte</th><th>Bit-Bereich</th><th>Feldname</th><th>Breite</th><th>Beschreibung &amp; Wertebereich</th></tr></thead><tbody><tr><td><strong>Byte 0</strong></td><td>Bit 7 (MSB) .. 4 (LSB)</td><td><code>Protocol Version</code></td><td>4 Bits</td><td>Version des IDS-Protokolls zur Gewährleistung von Interoperabilität und Dekodierbarkeit über Plattform-Releases hinweg.</td></tr><tr><td><strong>Byte 0</strong></td><td>Bit 3 (MSB) .. 0 (LSB)</td><td><code>Protocol Header</code></td><td>4 Bits</td><td>Steuerungsinformationen / Flags (z. B. Indikatoren für nachfolgende optionale Segmente: Timestamp, Context Data, Authenticator).</td></tr><tr><td><strong>Byte 1–2</strong></td><td>Byte 1 Bit 7..0 &amp; Byte 2 Bit 7..6</td><td><code>IdsM Instance ID</code></td><td>10 Bits</td><td>Eindeutige Instanzkennung des meldenden IdsM-Moduls im Steuergeräte-Verbund (Wertbereich: 0 .. 1023).</td></tr><tr><td><strong>Byte 2</strong></td><td>Byte 2 Bit 5 (MSB) .. 0 (LSB)</td><td><code>Sensor Instance ID</code></td><td>6 Bits</td><td>Identifikator der meldenden Sensor-Instanz (Hard- oder Software-Sensor innerhalb der Plattform, Wertbereich: 0 .. 63).</td></tr><tr><td><strong>Byte 3–4</strong></td><td>Byte 3 Bit 7..0 &amp; Byte 4 Bit 7..0</td><td><code>Event Definition ID</code></td><td>16 Bits</td><td>Standardisierte oder herstellerspezifische Vorfall-ID (Security Event Typ gem. AUTOSAR Security Event Katalog / ARXML).</td></tr><tr><td><strong>Byte 5–6</strong></td><td>Byte 5 Bit 7..0 &amp; Byte 6 Bit 7..0</td><td><code>Count</code></td><td>16 Bits</td><td>Monoton steigender Sequenz- bzw. Ereigniszähler (Erkennung von Event-Aggregation, Burst-Verhalten oder Frame-Loss / Anti-Replay).</td></tr><tr><td><strong>Byte 7</strong></td><td>Bit 7 (MSB) .. 0 (LSB)</td><td><code>Reserved</code></td><td>8 Bits</td><td>Reserviertes Padding-/Zukunftsfeld; standardmäßig auf <code>0x00</code> zu setzen (sofern nicht durch spätere Profile redefiniert).</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Ein On-Board-Sensor (z. B. CanSM/CanIf-Filter, SecOC-MAC-Fehler, Firewall, Dem oder Applikations-SW-C) detektiert eine Security-Anomalie und ruft die IdsM-API auf:\n<ul class=\"fig-list\"><li>CP: <code>IdsM_SetSecurityEvent(EventDefinitionId, ...)</code>\n</li><li>AP: <code>ara::idsm::ReportSecurityEvent(...)</code>\n</li></ul>\n</li><li><strong>Filterung &amp; Aggregation (IdsM-intern):</strong>\n<ul class=\"fig-list\"><li>Der IdsM validiert und filtert das Event (Thresholding, Rate-Limiting, Blacklisting).\n</li><li>Bei wiederholtem Auftreten desselben Events innerhalb eines Aggregationsintervalls wird der <code>Count</code>-Parameter inkrementiert, anstatt für jeden Vorfall eine separate Bus-PDU zu erzeugen.\n</li></ul>\n</li><li><strong>PDU-Serialisierung (Big-Endian-Serialisierung):</strong>\n<ul class=\"fig-list\"><li>Der IdsM generiert den 8-Byte-<code>Event Frame</code> strikt in Network Byte Order (Byte 0 zuerst; MSB in Bit 7).\n</li><li>Wenn konfiguriert, werden Zeitstempel (via StbM) und Kontextdaten angehängt sowie ein Signature-Trailer via CSM/SecOC ergänzt.\n</li></ul>\n</li><li><strong>PDU-Übergabe an den Communication Stack:</strong>\n<ul class=\"fig-list\"><li>Übergabe als I-PDU an PduR / Com bzw. Ethernet Socket/SOME/IP.\n</li><li>Asynchrone Sendebestätigung über <code>TxConfirmation</code>. Fehlerbehandlung bei Sendeverzug oder PDU-Pufferüberlauf erfolgt via Det (<code>IDSM_E_PARAM_POINTER</code>, <code>IDSM_E_FIFO_OVERFLOW</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Endianness (<code>[PRS_Ids_00004]</code>):</strong> \n<ul class=\"fig-list\"><li>Verbindliche Ausrichtung auf <strong>Big-Endian (Motorola-Format)</strong>. Auf Little-Endian-Zielarchitekturen (z. B. ARM Cortex-M/R/A, x86/AURIX-spezifische Little-Endian-Cores) ist eine explizite Byte-/Bit-Invertierung bzw. Shift-Maskierung für die 10-Bit (<code>IdsM Instance ID</code>) und 16-Bit (<code>Event Definition ID</code>, <code>Count</code>) Multi-Byte-Werte zwingend erforderlich.\n</li></ul>\n</li><li><strong>Byte-Übergreifende Bitfelder (Byte 1 &amp; Byte 2):</strong>\n<ul class=\"fig-list\"><li><code>IdsM Instance ID</code> überspannt die Grenze zwischen Byte 1 und Byte 2 (Bit 7..6). Es darf kein naiver C-Bitfield-Struct verwendet werden, da Compiler-Implementierungen bezüglich Bitfeld-Packing und Endianness nicht portabel sind. Bit-Maskierung muss über standardisierte Shift-Operationen realisiert werden:\n $$\\text{Byte 1} = (\\text{IdsM\\_InstanceId} \\gg 2) \\ \\&amp; \\ \\text{0xFF}$$\n $$\\text{Byte 2} = ((\\text{IdsM\\_InstanceId} \\ \\&amp; \\ \\text{0x03}) \\ll 6) \\mid (\\text{Sensor\\_InstanceId} \\ \\&amp; \\ \\text{0x3F})$$\n</li></ul>\n</li><li><strong>CAN-Payload-Optimierung (<code>[PRS_Ids_00005]</code>, <code>[PRS_Ids_00006]</code>):</strong>\n<ul class=\"fig-list\"><li>Werden für ein Event weder Kontextdaten noch Timestamps/Signaturen konfiguriert (<code>Protocol Header = 0</code>), entspricht die resultierende PDU exakt 8 Bytes. Dies ermöglicht die direkte Übertragung via Classical CAN ohne Transportprotokoll (CanTp).\n</li></ul>\n</li><li><strong>Konfigurationsverträge (ARXML / BswM):</strong>\n<ul class=\"fig-list\"><li><code>Event Definition ID</code> muss konsistent mit dem BSW-Modul <code>IdsM</code> über standardisierte IDs aus dem Security-Modell gemappt sein.\n</li><li>Das <code>Reserved</code>-Byte (Byte 7) muss vom Transmitter auf <code>0x00</code> initialisiert und vom Receiver tolerant behandelt (ignoriert) werden, um Vorwärtskompatibilität zu wahren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6eee94231fed8643", "to": "FIG-54798a7e9de401df", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-54798a7e9de401df", "to": "FIG-831d59b7d249c1c8", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Das optionale Rahmenfeld im übergeordneten Protokollverbund wurde von <code>Signature Frame</code> in <code>Authenticator Frame</code> umbenannt.\n</li></ul>"}]};
